package io.github.aryan52.tenantflow.storage;

import java.io.InputStream;

/**
 * Minimal object-storage abstraction (S3-compatible in every real environment). Keys are
 * always generated by the application; implementations must never interpret them as
 * filesystem paths.
 */
public interface ObjectStorage {

	void put(String key, InputStream content, long length, String contentType);

	/** Caller must close the returned stream. */
	InputStream get(String key);

	void delete(String key);
}
